/**
 * Wortklar verb seed.
 *
 * Row: [lemma, en, ru, exDe, exEn, exRu, level, topics, frequency, flags?, conjugations?, illustration?]
 * flags: {irregular, separable, reflexive, auxiliary:'haben'|'sein'|'haben/sein'}
 * conjugations: PRESENT tense, {ich,du,er,wir,ihr,sie}. Values omit the pronoun;
 *   reflexive pronoun and separable prefix are appended ("wasche mich", "komme an").
 */
import { conjugateWeak } from '../lib/conjugator.mjs';

const PR = ['ich', 'du', 'er', 'wir', 'ihr', 'sie'];
const RA = ['mich', 'dich', 'sich', 'uns', 'euch', 'sich'];
const RD = ['mir', 'dir', 'sich', 'uns', 'euch', 'sich'];

const build = (forms, o) =>
  Object.fromEntries(
    PR.map((p, i) => [
      p,
      [forms[i], o.rf ? (o.rf === 'd' ? RD[i] : RA[i]) : '', o.pre || ''].filter(Boolean).join(' '),
    ]),
  );

/** J(infinitive-without-prefix/sich, du?, er?, opts?) — regular pattern with optional du/er overrides. */
const J = (inf, du, er, o) => {
  if (du && typeof du === 'object') { o = du; du = undefined; er = undefined; }
  o = o || {};
  const b = conjugateWeak(inf);
  return build(
    [o.ich || b.ich, du || b.du, er || b.er, b.wir, o.ihr || b.ihr, b.sie],
    o,
  );
};
/** C(ich,du,er,wir,ihr,sie, opts?) — fully explicit present forms. */
const C = (a, b, c, d, e, f, o) => build([a, b, c, d, e, f], o || {});

/** flags helper: i=irregular, sep=separable, rf=reflexive, sein, hs=haben/sein */
const fl = (...k) => {
  const o = {};
  for (const x of k) {
    if (x === 'i') o.irregular = true;
    else if (x === 'sep') o.separable = true;
    else if (x === 'rf') o.reflexive = true;
    else if (x === 'sein') o.auxiliary = 'sein';
    else if (x === 'hs') o.auxiliary = 'haben/sein';
  }
  return o;
};

